"""Building blocks of a tiny RAG pipeline (no external services)."""
import math
import re
from collections import Counter


def chunk_text(text, chunk_size, overlap=0):
    if chunk_size <= 0 or overlap < 0 or overlap >= chunk_size:
        raise ValueError("need chunk_size > 0 and 0 <= overlap < chunk_size")
    words = text.split()
    chunks, i, step = [], 0, chunk_size - overlap
    while i < len(words):
        chunks.append(" ".join(words[i:i + chunk_size]))
        if i + chunk_size >= len(words):
            break
        i += step
    return chunks


def _tokens(text):
    return re.findall(r"[a-z0-9]+", text.lower())


class TfidfRetriever:
    def __init__(self, chunks):
        self.chunks = list(chunks)
        docs = [Counter(_tokens(c)) for c in self.chunks]
        n = len(docs)
        df = Counter()
        for d in docs:
            df.update(d.keys())
        self.idf = {t: math.log((1 + n) / (1 + f)) + 1 for t, f in df.items()}
        self.vectors = [self._vector(d) for d in docs]

    def _vector(self, counts):
        total = sum(counts.values()) or 1
        vec = {t: (c / total) * self.idf[t] for t, c in counts.items() if t in self.idf}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        return vec, norm

    def search(self, query, k=3):
        if k <= 0 or not self.chunks:
            return []
        qvec, qnorm = self._vector(Counter(_tokens(query)))
        if qnorm == 0:
            return []
        scored = []
        for i, (vec, norm) in enumerate(self.vectors):
            if norm == 0:
                continue
            dot = sum(w * vec.get(t, 0.0) for t, w in qvec.items())
            score = dot / (qnorm * norm)
            if score > 0:
                scored.append((i, score))
        scored.sort(key=lambda p: (-p[1], p[0]))
        return scored[:k]


def build_prompt(question, contexts):
    if contexts:
        body = "\n".join(f"[{i}] {c}" for i, c in enumerate(contexts, start=1))
    else:
        body = "(no context)"
    return (
        'Answer the question using only the context below. If the answer is not in the context, say "I don\'t know".\n\n'
        f"Context:\n{body}\n\nQuestion: {question}\nAnswer:"
    )
